def make_test(starts):
    g=[[3]*27 for _ in range(27)]
    for r,vals in pattern.items():
        for c,v in vals.items(): g[r][c]=v
    for br,row in enumerate(block_colors):
        for bc,color in enumerate(row):
            if color:
                r0=starts[br]; c0=13+5*bc
                for r in range(r0,r0+4):
                    for c in range(c0,c0+4): g[r][c]=color
    return g
